const COUNT = 4

game lu_run
game lu_go

process lu_count(id: number) {
    left = COUNT
    while left > 0 {
        if lu_run != id {
            return
        }
        @all send_title("&e${left}", fade_in: 0, stay: 25, fade_out: 5)
        @all send_message("lu_count ${id} ${left}")
        wait(1, seconds)
        left -= 1
    }
    if lu_run == id {
        lu_go += 1
        @all send_title("&aСтарт!", fade_in: 0, stay: 25, fade_out: 5)
        @all send_message("lu_go ${id}")
    }
}

