func lu_clock(sec) {
    return format_timestamp(sec * 1000, "mm:ss", format: custom)
}

when player_chat {
    if chat_message_equals("@lu_clock") {
        cancel_event()
        send_message("lu_clock ${lu_clock(75)} ${lu_clock(3599)}")
    }
    if chat_message_equals("@lu_cd") {
        cancel_event()
        if value.timestamp < `lu_next %player%` {
            left = ceil((`lu_next %player%` - value.timestamp) / 1000)
            send_message("lu_wait ${lu_clock(left)}")
            end_thread()
        }
        `lu_next %player%` = value.timestamp
        `lu_next %player%` += 3000
        send_message("lu_ready")
    }
}

process lu_work(total: number) {
    done = 0
    for i in 1..total {
        done += 1
        if remainder(i, 500) == 0 {
            wait(1)
            while value.cpu_usage >= 70 {
                wait(1)
            }
        }
    }
    send_message("lu_work ${done}")
}

