const NEED = 1

func lu_count_down(total, label) {
    left = total
    while left > 0 and len(lu_players) >= NEED {
        @all set_boss_bar("lu_round", "${label} ${left}", 100 * left / total, color: green)
        wait(1, seconds)
        left -= 1
    }
}

process lu_match() {
    lu_games += 1
    lu_count_down(1, "&eСтарт через")
    if left == 0 {
        lu_phase = "run"
        player_by_conditional(@current value.name in lu_players)
        send_title("&aСтарт!", fade_in: 5, stay: 20, fade_out: 5)
        reset()
        @all send_message("lu_run ${lu_games}")
        lu_count_down(3, "&fОсталось")
        lu_players = []
    }
    @all remove_boss_bar("lu_round")
    @all set_gamemode(gamemode: adventure)
    @all send_message("lu_end ${lu_games} ${left}")
    lu_phase = "lobby"
}

when world_start {
    game lu_phase = "lobby"
    game lu_players = []
    game lu_games = 0
}

when player_join {
    if lu_phase == "run" {
        set_gamemode(gamemode: spectator)
    }
}

when player_quit {
    lu_players = remove_list_value(lu_players, value.name, remove_mode: all)
}

when player_chat {
    if chat_message_equals("@lu_play") {
        cancel_event()
        if lu_phase == "run" or value.name in lu_players {
            send_message("lu_no")
            end_thread()
        }
        lu_players = append_value(value.name)
        if lu_phase == "lobby" and len(lu_players) >= NEED {
            lu_phase = "count"
            start lu_match(target_mode: no_target)
        }
    }
    if chat_message_equals("@lu_leave") {
        cancel_event()
        lu_players = remove_list_value(lu_players, value.name, remove_mode: all)
    }
    if chat_message_equals("@lu_state") {
        cancel_event()
        send_message("lu_state ${lu_phase} ${len(lu_players)}")
    }
}

func lu_deal(names) {
    game lu_team = {}
    for i, name in randomize_list_order(names) {
        lu_team[name] = remainder(i, 2) == 0 ? "red" : "blue"
    }
}

when player_damage_player {
    if "%damager%" in lu_team and lu_team["%damager%"] == lu_team["%victim%"] {
        cancel_event()
    }
}

when player_chat {
    if chat_message_equals("@lu_team") {
        cancel_event()
        lu_deal(["a", "b", "c", "d", value.name])
        reds = 0
        for name: side in lu_team {
            if side == "red" {
                reds += 1
            }
        }
        send_message("lu_team ${reds} ${len(lu_team)} ${lu_team[value.name]}")
    }
}
